1	//! Typed gRPC reflection descriptors synthesized from `PluginSchema.methods`
2	//! (REQ-6.1): per-method `FileDescriptorProto`s with real field types derived
3	//! from `MethodDecl.args` / `MethodDecl.returns` JSON Schemas — never
4	//! `google.protobuf.Struct`.
5	//!
6	//! Naming follows the spec's acceptance criterion (Task 3.2):
7	//!
8	//! ```text
9	//! file:    operation/method/<plugin>/<method>.proto
10	//! package: operation.method.<plugin>.<method>
11	//! service: <Method>Service   rpc <Method>(<Method>Input) returns (<Method>Output)
12	//! ```
13	//!
14	//! The protobuf wire encoding is written by hand (varint + length-delimited
15	//! fields of descriptor.proto messages) so the crate stays dependency-free.
16	//! The bytes are a valid `google.protobuf.FileDescriptorSet` consumable by
17	//! tonic-reflection / grpcurl.
18	
19	use crate::schema::{MethodDecl, PluginSchema};
20	use serde_json::Value as JVal;
21	
22	// FieldDescriptorProto.Type values (descriptor.proto)
23	const T_DOUBLE: u64 = 1;
24	const T_INT64: u64 = 3;
25	const T_BOOL: u64 = 8;
26	const T_STRING: u64 = 9;
27	const T_MESSAGE: u64 = 11;
28	// FieldDescriptorProto.Label values
29	const L_OPTIONAL: u64 = 1;
30	const L_REPEATED: u64 = 3;
31	
32	/// One synthesized per-method descriptor file plus its reflection index keys.
33	#[derive(Debug, Clone)]
34	pub struct MethodDescriptor {
35	    pub method_name: String,
36	    pub file_name: String,
37	    pub package: String,
38	    /// Fully-qualified service name, e.g. `operation.method.unix_socket.bind.BindService`.
39	    pub service_full: String,
40	    /// `/package.Service/Rpc` — the callable route path.
41	    pub grpc_path: String,
42	    pub input_full: String,
43	    pub output_full: String,
44	    /// All fully-qualified symbols this file defines (for symbol lookup).
45	    pub symbols: Vec<String>,
46	    /// Encoded `FileDescriptorProto` bytes.
47	    pub file_descriptor_proto: Vec<u8>,
48	}
49	
50	/// Synthesize the full `FileDescriptorSet` for one plugin, one file per
51	/// method, sorted by method name for byte determinism (NFR-2).
52	pub fn descriptor_set_for_plugin(
53	    plugin_id: &str,
54	    schema: &PluginSchema,
55	) -> (Vec<u8>, Vec<MethodDescriptor>) {
56	    let mut names: Vec<&String> = schema.methods.keys().collect();
57	    names.sort();
58	    let mut infos = Vec::new();
59	    let mut set = Vec::new();
60	    for name in names {
61	        let info = method_file_descriptor(plugin_id, &schema.methods[name]);
62	        // FileDescriptorSet.file = 1 (repeated message)
63	        put_bytes(&mut set, 1, &info.file_descriptor_proto);
64	        infos.push(info);
65	    }
66	    (set, infos)
67	}
68	
69	/// Build one per-method `FileDescriptorProto` with typed Input/Output messages.
70	pub fn method_file_descriptor(plugin_id: &str, method: &MethodDecl) -> MethodDescriptor {
71	    let snake = snake_case(&method.name);
72	    let pascal = pascal_case(&method.name);
73	    let package = format!("operation.method.{plugin_id}.{snake}");
74	    let file_name = format!("operation/method/{plugin_id}/{snake}.proto");
75	
76	    let input_msg = message_from_json_schema(&format!("{pascal}Input"), &method.args);
77	    let empty = serde_json::json!({"type": "object"});
78	    let output_schema = method.returns.as_ref().unwrap_or(&empty);
79	    let output_msg = message_from_json_schema(&format!("{pascal}Output"), output_schema);
80	
81	    let input_full = format!("{package}.{pascal}Input");
82	    let output_full = format!("{package}.{pascal}Output");
83	    let service_full = format!("{package}.{pascal}Service");
84	
85	    // MethodDescriptorProto
86	    let mut m = Vec::new();
87	    put_str(&mut m, 1, &pascal);
88	    put_str(&mut m, 2, &format!(".{input_full}"));
89	    put_str(&mut m, 3, &format!(".{output_full}"));
90	
91	    // ServiceDescriptorProto
92	    let mut svc = Vec::new();
93	    put_str(&mut svc, 1, &format!("{pascal}Service"));
94	    put_bytes(&mut svc, 2, &m);
95	
96	    // FileDescriptorProto
97	    let mut file = Vec::new();
98	    put_str(&mut file, 1, &file_name);
99	    put_str(&mut file, 2, &package);
100	    put_bytes(&mut file, 4, &encode_message(&input_msg));
101	    put_bytes(&mut file, 4, &encode_message(&output_msg));
102	    put_bytes(&mut file, 6, &svc);
103	    put_str(&mut file, 12, "proto3");
104	
105	    let mut symbols = vec![
106	        service_full.clone(),
107	        input_full.clone(),
108	        output_full.clone(),
109	    ];
110	    symbols.push(format!("{service_full}.{pascal}"));
111	    collect_nested_symbols(
112	        &input_msg,
113	        &format!("{package}.{}", input_msg.name),
114	        &mut symbols,
115	    );
116	    collect_nested_symbols(
117	        &output_msg,
118	        &format!("{package}.{}", output_msg.name),
119	        &mut symbols,
120	    );
121	
122	    MethodDescriptor {
123	        method_name: method.name.clone(),
124	        grpc_path: format!("/{service_full}/{pascal}"),
125	        file_name,
126	        package,
127	        service_full,
128	        input_full,
129	        output_full,
130	        symbols,
131	        file_descriptor_proto: file,
132	    }
133	}
134	
135	// ---------------------------------------------------------------------------
136	// JSON Schema -> DescriptorProto message synthesis
137	// ---------------------------------------------------------------------------
138	
139	struct MessageDef {
140	    name: String,
141	    fields: Vec<FieldDef>,
142	    nested: Vec<MessageDef>,
143	}
144	
145	struct FieldDef {
146	    name: String,
147	    number: u64,
148	    repeated: bool,
149	    proto_type: u64,
150	    /// Relative type name for `T_MESSAGE` fields (a nested message).
151	    type_name: Option<String>,
152	}
153	
154	/// Walk a schemars JSON Schema document into a proto message definition.
155	/// Objects with properties become nested messages; scalars map directly;
156	/// enums/unknown/any degrade to string (JSON-encoded).
157	fn message_from_json_schema(msg_name: &str, schema: &JVal) -> MessageDef {
158	    let defs = schema
159	        .get("$defs")
160	        .or_else(|| schema.get("definitions"))
161	        .and_then(JVal::as_object);
162	    build_message(msg_name, resolve(schema, defs), defs)
163	}
164	
165	fn build_message(
166	    name: &str,
167	    node: &JVal,
168	    defs: Option<&serde_json::Map<String, JVal>>,
169	) -> MessageDef {
170	    let mut fields = Vec::new();
171	    let mut nested = Vec::new();
172	    if let Some(props) = node.get("properties").and_then(JVal::as_object) {
173	        // serde_json Map is BTreeMap-backed: iteration (and thus field
174	        // numbering) is name-sorted and deterministic.
175	        for (i, (fname, fnode)) in props.iter().enumerate() {
176	            let number = (i + 1) as u64;
177	            let (repeated, item) = match unwrap_array(fnode, defs) {
178	                Some(item) => (true, item),
179	                None => (false, resolve(fnode, defs).clone()),
180	            };
181	            let (proto_type, type_name) = proto_type_of(&item, defs, fname, &mut nested);
182	            fields.push(FieldDef {
183	                name: fname.clone(),
184	                number,
185	                repeated,
186	                proto_type,
187	                type_name,
188	            });
189	        }
190	    }
191	    MessageDef {
192	        name: name.to_string(),
193	        fields,
194	        nested,
195	    }
196	}
197	
198	/// If `node` is an array schema, return its resolved item schema.
199	fn unwrap_array(node: &JVal, defs: Option<&serde_json::Map<String, JVal>>) -> Option<JVal> {
200	    let node = resolve(node, defs);
201	    if json_type(node) == Some("array") {
202	        let item = node.get("items").map(|i| resolve(i, defs).clone());
203	        Some(item.unwrap_or(serde_json::json!({})))
204	    } else {
205	        None
206	    }
207	}
208	
209	fn proto_type_of(
210	    node: &JVal,
211	    defs: Option<&serde_json::Map<String, JVal>>,
212	    field_name: &str,
213	    nested: &mut Vec<MessageDef>,
214	) -> (u64, Option<String>) {
215	    let node = resolve(node, defs);
216	
217	    // Option<T>: collapse anyOf [T, null] to T.
218	    if let Some(alts) = node
219	        .get("anyOf")
220	        .or_else(|| node.get("oneOf"))
221	        .and_then(JVal::as_array)
222	    {
223	        let non_null: Vec<&JVal> = alts
224	            .iter()
225	            .filter(|a| json_type(a) != Some("null"))
226	            .collect();
227	        if let [single] = non_null.as_slice() {
228	            return proto_type_of(single, defs, field_name, nested);
229	        }
230	        // Multi-branch union: JSON-encoded string.
231	        return (T_STRING, None);
232	    }
233	
234	    match json_type(node) {
235	        Some("string") => (T_STRING, None),
236	        Some("integer") => (T_INT64, None),
237	        Some("number") => (T_DOUBLE, None),
238	        Some("boolean") => (T_BOOL, None),
239	        Some("object") if node.get("properties").is_some() => {
240	            let msg_name = format!("{}Msg", pascal_case(field_name));
241	            let def = build_message(&msg_name, node, defs);
242	            nested.push(def);
243	            (T_MESSAGE, Some(msg_name))
244	        }
245	        // enum / free-form object / any -> JSON-encoded string
246	        _ => (T_STRING, None),
247	    }
248	}
249	
250	fn resolve<'a>(node: &'a JVal, defs: Option<&'a serde_json::Map<String, JVal>>) -> &'a JVal {
251	    if let (Some(r), Some(d)) = (node.get("$ref").and_then(JVal::as_str), defs) {
252	        if let Some(key) = r.rsplit('/').next() {
253	            if let Some(target) = d.get(key) {
254	                return resolve(target, defs);
255	            }
256	        }
257	    }
258	    node
259	}
260	
261	fn json_type(node: &JVal) -> Option<&str> {
262	    match node.get("type") {
263	        Some(JVal::String(s)) => Some(s.as_str()),
264	        Some(JVal::Array(a)) => a.iter().filter_map(JVal::as_str).find(|t| *t != "null"),
265	        _ => None,
266	    }
267	}
268	
269	fn collect_nested_symbols(msg: &MessageDef, full: &str, out: &mut Vec<String>) {
270	    for n in &msg.nested {
271	        let child = format!("{full}.{}", n.name);
272	        out.push(child.clone());
273	        collect_nested_symbols(n, &child, out);
274	    }
275	}
276	
277	// ---------------------------------------------------------------------------
278	// descriptor.proto wire encoding
279	// ---------------------------------------------------------------------------
280	
281	fn encode_message(def: &MessageDef) -> Vec<u8> {
282	    // DescriptorProto: name=1, field=2, nested_type=3
283	    let mut out = Vec::new();
284	    put_str(&mut out, 1, &def.name);
285	    for f in &def.fields {
286	        // FieldDescriptorProto: name=1, number=3, label=4, type=5, type_name=6, json_name=10
287	        let mut fd = Vec::new();
288	        put_str(&mut fd, 1, &f.name);
289	        put_varint_field(&mut fd, 3, f.number);
290	        put_varint_field(&mut fd, 4, if f.repeated { L_REPEATED } else { L_OPTIONAL });
291	        put_varint_field(&mut fd, 5, f.proto_type);
292	        if let Some(t) = &f.type_name {
293	            // Relative reference resolves against the enclosing scope.
294	            put_str(&mut fd, 6, t);
295	        }
296	        put_str(&mut fd, 10, &json_name(&f.name));
297	        put_bytes(&mut out, 2, &fd);
298	    }
299	    for n in &def.nested {
300	        put_bytes(&mut out, 3, &encode_message(n));
301	    }
302	    out
303	}
304	
305	fn put_varint(out: &mut Vec<u8>, mut v: u64) {
306	    loop {
307	        let b = (v & 0x7f) as u8;
308	        v >>= 7;
309	        if v == 0 {
310	            out.push(b);
311	            break;
312	        }
313	        out.push(b | 0x80);
314	    }
315	}
316	
317	fn put_tag(out: &mut Vec<u8>, field: u32, wire: u8) {
318	    put_varint(out, ((field as u64) << 3) | wire as u64);
319	}
320	
321	fn put_varint_field(out: &mut Vec<u8>, field: u32, v: u64) {
322	    put_tag(out, field, 0);
323	    put_varint(out, v);
324	}
325	
326	fn put_str(out: &mut Vec<u8>, field: u32, s: &str) {
327	    put_bytes(out, field, s.as_bytes());
328	}
329	
330	fn put_bytes(out: &mut Vec<u8>, field: u32, b: &[u8]) {
331	    put_tag(out, field, 2);
332	    put_varint(out, b.len() as u64);
333	    out.extend_from_slice(b);
334	}
335	
336	fn json_name(snake: &str) -> String {
337	    let mut out = String::new();
338	    let mut upper = false;
339	    for c in snake.chars() {
340	        if c == '_' {
341	            upper = true;
342	        } else if upper {
343	            out.extend(c.to_uppercase());
344	            upper = false;
345	        } else {
346	            out.push(c);
347	        }
348	    }
349	    out
350	}
351	
352	pub fn pascal_case(s: &str) -> String {
353	    let mut out = String::new();
354	    let mut upper = true;
355	    for c in s.chars() {
356	        if c == '_' || c == '-' || c == '.' {
357	            upper = true;
358	        } else if upper {
359	            out.extend(c.to_uppercase());
360	            upper = false;
361	        } else {
362	            out.push(c);
363	        }
364	    }
365	    out
366	}
367	
368	pub fn snake_case(s: &str) -> String {
369	    let mut out = String::new();
370	    for (i, c) in s.chars().enumerate() {
371	        if c.is_uppercase() {
372	            if i > 0 && !out.ends_with('_') {
373	                out.push('_');
374	            }
375	            out.extend(c.to_lowercase());
376	        } else if c == '-' || c == '.' {
377	            out.push('_');
378	        } else {
379	            out.push(c);
380	        }
381	    }
382	    out
383	}
384	
385	// ---------------------------------------------------------------------------
386	// Minimal FileDescriptorSet decoding — enough for reflection indexing,
387	// catalog `file_by_filename`, and tests. Returns borrowed subslices of the
388	// input (zero-copy).
389	// ---------------------------------------------------------------------------
390	
391	/// Summary of one file entry inside an encoded `FileDescriptorSet`, borrowing
392	/// the underlying descriptor bytes.
393	#[derive(Debug)]
394	pub struct FileSummary<'a> {
395	    pub name: String,
396	    pub package: String,
397	    pub messages: Vec<String>,
398	    pub services: Vec<String>,
399	    /// Borrowed `FileDescriptorProto` bytes within the set.
400	    pub bytes: &'a [u8],
401	}
402	
403	/// Iterate the `file` entries of an encoded `FileDescriptorSet`.
404	pub fn decode_file_summaries(set: &[u8]) -> Result<Vec<FileSummary<'_>>, String> {
405	    let mut out = Vec::new();
406	    let mut r = Reader { buf: set, pos: 0 };
407	    while !r.done() {
408	        let (field, wire) = r.tag()?;
409	        if field == 1 && wire == 2 {
410	            let bytes = r.len_delim()?;
411	            out.push(decode_file_summary(bytes)?);
412	        } else {
413	            r.skip(wire)?;
414	        }
415	    }
416	    Ok(out)
417	}
418	
419	fn decode_file_summary(bytes: &[u8]) -> Result<FileSummary<'_>, String> {
420	    let mut s = FileSummary {
421	        name: String::new(),
422	        package: String::new(),
423	        messages: Vec::new(),
424	        services: Vec::new(),
425	        bytes,
426	    };
427	    let mut r = Reader { buf: bytes, pos: 0 };
428	    while !r.done() {
429	        let (field, wire) = r.tag()?;
430	        match (field, wire) {
431	            (1, 2) => s.name = r.string()?,
432	            (2, 2) => s.package = r.string()?,
433	            (4, 2) => s.messages.push(first_string_field(r.len_delim()?)?),
434	            (6, 2) => s.services.push(first_string_field(r.len_delim()?)?),
435	            _ => r.skip(wire)?,
436	        }
437	    }
438	    Ok(s)
439	}
440	
441	/// Read field #1 (name) of a DescriptorProto/ServiceDescriptorProto.
442	fn first_string_field(bytes: &[u8]) -> Result<String, String> {
443	    let mut r = Reader { buf: bytes, pos: 0 };
444	    while !r.done() {
445	        let (field, wire) = r.tag()?;
446	        if field == 1 && wire == 2 {
447	            return r.string();
448	        }
449	        r.skip(wire)?;
450	    }
451	    Ok(String::new())
452	}
453	
454	struct Reader<'a> {
455	    buf: &'a [u8],
456	    pos: usize,
457	}
458	
459	impl<'a> Reader<'a> {
460	    fn done(&self) -> bool {
461	        self.pos >= self.buf.len()
462	    }
463	
464	    fn varint(&mut self) -> Result<u64, String> {
465	        let mut v = 0u64;
466	        let mut shift = 0;
467	        loop {
468	            let b = *self
469	                .buf
470	                .get(self.pos)
471	                .ok_or_else(|| "varint overruns buffer".to_string())?;
472	            self.pos += 1;
473	            v |= ((b & 0x7f) as u64) << shift;
474	            if b & 0x80 == 0 {
475	                return Ok(v);
476	            }
477	            shift += 7;
478	            if shift > 63 {
479	                return Err("varint too long".into());
480	            }
481	        }
482	    }
483	
484	    fn tag(&mut self) -> Result<(u32, u8), String> {
485	        let t = self.varint()?;
486	        Ok(((t >> 3) as u32, (t & 7) as u8))
487	    }
488	
489	    fn len_delim(&mut self) -> Result<&'a [u8], String> {
490	        let len = self.varint()? as usize;
491	        let end = self.pos + len;
492	        if end > self.buf.len() {
493	            return Err("length-delimited field overruns buffer".into());
494	        }
495	        let s = &self.buf[self.pos..end];
496	        self.pos = end;
497	        Ok(s)
498	    }
499	
500	    fn string(&mut self) -> Result<String, String> {
501	        Ok(String::from_utf8_lossy(self.len_delim()?).into_owned())
502	    }
503	
504	    fn skip(&mut self, wire: u8) -> Result<(), String> {
505	        match wire {
506	            0 => {
507	                self.varint()?;
508	            }
509	            1 => self.pos += 8,
510	            2 => {
511	                self.len_delim()?;
512	            }
513	            5 => self.pos += 4,
514	            w => return Err(format!("unsupported wire type {w}")),
515	        }
516	        if self.pos > self.buf.len() {
517	            return Err("skip overruns buffer".into());
518	        }
519	        Ok(())
520	    }
521	}
522	
523	#[cfg(test)]
524	mod tests {
525	    use super::*;
526	    use crate::adapter::{method_decl_from_schemars_with_output, AckOutput};
527	    use crate::schema::SideEffect;
528	    use serde::{Deserialize, Serialize};
529	
530	    #[derive(Serialize, Deserialize, schemars::JsonSchema)]
531	    struct SetDeviceInput {
532	        interface: String,
533	        private_key: String,
534	        listen_port: Option<u16>,
535	        fwmark: Option<u32>,
536	    }
537	
538	    #[test]
539	    fn typed_descriptor_matches_spec_naming() {
540	        let decl = method_decl_from_schemars_with_output::<SetDeviceInput, AckOutput>(
541	            "set_device",
542	            SideEffect::Mutation,
543	            false,
544	            "wireguard.write",
545	            "mut.network.wireguard.set-device@v1",
546	        );
547	        let d = method_file_descriptor("wireguard", &decl);
548	        assert_eq!(d.package, "operation.method.wireguard.set_device");
549	        assert_eq!(
550	            d.service_full,
551	            "operation.method.wireguard.set_device.SetDeviceService"
552	        );
553	        assert_eq!(
554	            d.input_full,
555	            "operation.method.wireguard.set_device.SetDeviceInput"
556	        );
557	        assert_eq!(
558	            d.grpc_path,
559	            "/operation.method.wireguard.set_device.SetDeviceService/SetDevice"
560	        );
561	
562	        // Round-trip through the wire decoder: real typed messages, no Struct.
563	        let mut set = Vec::new();
564	        put_bytes(&mut set, 1, &d.file_descriptor_proto);
565	        let files = decode_file_summaries(&set).unwrap();
566	        assert_eq!(files.len(), 1);
567	        assert_eq!(files[0].name, "operation/method/wireguard/set_device.proto");
568	        assert_eq!(files[0].services, vec!["SetDeviceService"]);
569	        assert_eq!(files[0].messages, vec!["SetDeviceInput", "SetDeviceOutput"]);
570	    }
571	
572	    #[test]
573	    fn case_conversions() {
574	        assert_eq!(pascal_case("set_device"), "SetDevice");
575	        assert_eq!(snake_case("SetDevice"), "set_device");
576	        assert_eq!(json_name("listen_port"), "listenPort");
577	    }
578	}
